import { pyRepr, pyTuple } from './pyrepr.mjs';

export class OMD {
  constructor() {
    this.pairs = [];
  }

  add(key, value) {
    this.pairs.push([key, value]);
  }

  getlist(key) {
    const values = [];
    for (const [k, v] of this.pairs) {
      if (k === key) values.push(v);
    }
    return values;
  }

  keys() {
    const keys = [];
    for (const [k] of this.pairs) {
      if (!keys.includes(k)) keys.push(k);
    }
    return keys;
  }

  items() {
    const result = [];
    for (const [k, v] of this.pairs) {
      const existing = result.find((t) => t.items[0] === k);
      if (existing) {
        existing.items[1] = v;
      } else {
        result.push(pyTuple(k, v));
      }
    }
    return result;
  }

  toString() {
    return `OrderedMultiDict(${pyRepr(this.pairs.map(([k, v]) => pyTuple(k, v)))})`;
  }
}

