const NON_PRINTABLE = /\p{Cc}|\p{Cf}|\p{Cs}|\p{Co}|\p{Zl}|\p{Zp}|\p{Zs}/u;

function escapeChar(ch) {
  const cp = ch.codePointAt(0);
  if (ch === '\\') return '\\\\';
  if (ch === '\n') return '\\n';
  if (ch === '\r') return '\\r';
  if (ch === '\t') return '\\t';
  if (NON_PRINTABLE.test(ch)) {
    if (cp < 0x100) return '\\x' + cp.toString(16).padStart(2, '0');
    if (cp < 0x10000) return '\\u' + cp.toString(16).padStart(4, '0');
    return '\\U' + cp.toString(16).padStart(8, '0');
  }
  return ch;
}

export function reprStr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    if (ch === quote) {
      out += '\\' + ch;
    } else {
      out += escapeChar(ch);
    }
  }
  return out + quote;
}

export class PyTuple {
  constructor(items) {
    this.items = items;
  }
}

export function pyTuple(...items) {
  return new PyTuple(items);
}

export function pyRepr(value) {
  if (typeof value === 'string') {
    return reprStr(value);
  }
  if (value instanceof PyTuple) {
    const parts = value.items.map(pyRepr);
    if (parts.length === 0) return '()';
    if (parts.length === 1) return '(' + parts[0] + ',)';
    return '(' + parts.join(', ') + ')';
  }
  if (Array.isArray(value)) {
    return '[' + value.map(pyRepr).join(', ') + ']';
  }
  return String(value);
}

