const OPTIONS = [
  { name: '--a', metavar: 'A', key: 'a' },
  { name: '--b', metavar: 'B', key: 'b' },
  { name: '--c', metavar: 'C', key: 'c' },
];

const LONG_NAMES = ['--help', '--a', '--b', '--c'];
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B --c C`;
}

function printHelp(prog) {
  const lines = [
    usageLine(prog),
    '',
    'options:',
    '  -h, --help  show this help message and exit',
    '  --a A',
    '  --b B',
    '  --c C',
  ];
  process.stdout.write(lines.join('\n') + '\n');
}

function fail(prog, message) {
  process.stderr.write(usageLine(prog) + '\n');
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

function isOptionLike(token) {
  if (token.length < 2 || token[0] !== '-') return false;
  if (NEGATIVE_NUMBER.test(token)) return false;
  return true;
}

function matchLong(head, prog) {
  let matches = LONG_NAMES.filter((n) => n === head);
  if (matches.length === 0) {
    matches = LONG_NAMES.filter((n) => n.startsWith(head));
  }
  if (matches.length > 1) {
    fail(prog, `ambiguous option: ${head} could match ${matches.join(', ')}`);
  }
  return matches.length === 1 ? matches[0] : null;
}

export function parseArgs(argv, prog) {
  const values = {};
  const seen = new Set();
  const extras = [];
  let optionsEnded = false;
  let i = 0;

  while (i < argv.length) {
    const token = argv[i];

    if (optionsEnded) {
      extras.push(token);
      i += 1;
      continue;
    }
    if (token === '--') {
      optionsEnded = true;
      i += 1;
      continue;
    }
    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      const head = eq === -1 ? token : token.slice(0, eq);
      const inlineValue = eq === -1 ? undefined : token.slice(eq + 1);
      const name = matchLong(head, prog);
      if (name === null) {
        extras.push(token);
        i += 1;
        continue;
      }
      if (name === '--help') {
        printHelp(prog);
        process.exit(0);
      }
      const opt = OPTIONS.find((o) => o.name === name);
      let val;
      if (inlineValue !== undefined) {
        val = inlineValue;
      } else {
        const next = argv[i + 1];
        if (next === undefined || isOptionLike(next)) {
          fail(prog, `argument ${opt.name}: expected one argument`);
        }
        val = next;
        i += 1;
      }
      values[opt.key] = val;
      seen.add(opt.name);
      i += 1;
      continue;
    }
    if (isOptionLike(token)) {
      if (token === '-h') {
        printHelp(prog);
        process.exit(0);
      }
      extras.push(token);
      i += 1;
      continue;
    }
    extras.push(token);
    i += 1;
  }

  const missing = OPTIONS.filter((o) => !seen.has(o.name)).map((o) => o.name);
  if (missing.length > 0) {
    fail(prog, `the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length > 0) {
    fail(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return { a: values.a, b: values.b, c: values.c };
}

